balanced-brackets.source:
def solve(text):
 stack=[]
 opening={')':'(',']':'[','}':'{'}
 for char in text:
  if char in '([{': stack.append(char)
  elif not stack or stack.pop()!=opening[char]: return False
 return True

shortest-distances.source:
def solve(graph,start):
 d=[-1]*len(graph)
 d[start]=0
 queue=[start]
 for u in queue:
  for v in graph[u]:
   if d[v]==-1: d[v]=d[u]+1; queue.append(v)
 return [max(0,x) for x in d]

def solve(graph,start):
 d=[-1]*len(graph)
 d[start]=0
 stack=[start]
 while stack:
  u=stack.pop()
  for v in graph[u]:
   if d[v]==-1: d[v]=d[u]+1; stack.append(v)
 return d

population-stats.source:
def solve(values):
 mean=sum(values)/len(values)
 return {'mean':mean,'variance':sum((x-mean)**2 for x in values)/(len(values)-1)}

def solve(values):
 mean=sum(values)/len(values)
 return {'mean':mean,'variance':sum(x*x for x in values)/len(values)-mean*mean}

