def solve(actual,predicted):
 e=[p-a for a,p in zip(actual,predicted)]
 return {'mae':sum(e)/len(e),'mse':sum(x*x for x in e)/len(e)}

def solve(actual,predicted):
 e=[p-a for a,p in zip(actual,predicted)]
 return {'mae':sum(abs(x) for x in e)/len(e),'mse':sum(x*x for x in e)}

